class Solution {
public:
    int romanToInt(string s) {
        unordered_map<string, int> values = {{"I",1},{"V",5},{"X",10},{"L",50},{"C",100},{"D",500},{"M",1000},{"IV",4},{"IX",9},{"XL",40},{"XC",90},{"CD",400},{"CM",900}};
        int total = 0;
        int n = s.size();
        for (int i = 0; i < n;) {
            if (i + 1 < n && values.count(s.substr(i, 2))) {
                total += values[s.substr(i, 2)];
                i += 2;
            } else {
                total += values[string(1, s[i])];
                i += 1;
            }
        }
        return total;
    }
};

