        values.put("IV", 4);
        values.put("IX", 9);
        values.put("XL", 40);
        values.put("XC", 90);
        values.put("CD", 400);
        values.put("CM", 900);
        int total = 0;
        int i = 0;
        while (i < s.length()) {
            if (i + 1 < s.length() && values.containsKey(s.substring(i, i + 2))) {
                total += values.get(s.substring(i, i + 2));
                i += 2;
            } else {
                total += values.get(s.substring(i, i + 1));
                i += 1;
            }
        }
        return total;
