class Solution {
public:
    int romanToInt(string s) {
        unordered_map<char, int> values = {{'I',1},{'V',5},{'X',10},{'L',50},{'C',100},{'D',500},{'M',1000}};
        int total = 0;
        int prev = 0;
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            int cur = values[s[i]];
            if (cur < prev) {
                total -= cur;
            } else {
                total += cur;
                prev = cur;
            }
        }
        return total;
    }
};

