class Solution {
    public int romanToInt(String s) {
        Map<Character, Integer> values = new HashMap<>();
        values.put('I', 1);
        values.put('V', 5);
        values.put('X', 10);
        values.put('L', 50);
        values.put('C', 100);
        values.put('D', 500);
        values.put('M', 1000);
        int total = 0;
        int prev = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            int cur = values.get(s.charAt(i));
            if (cur < prev) {
                total -= cur;
            } else {
                total += cur;
                prev = cur;
            }
        }
        return total;
    }
}
